#!/usr/bin/env bash
# Generated by scripts/assemble.py for harness "carto".
# Defensive scan: fail if any literal Datadog API/APP key shape is found
# anywhere in the harness directory.

set -uo pipefail

red()   { printf '\033[31m%s\033[0m\n' "$*"; }
green() { printf '\033[32m%s\033[0m\n' "$*"; }

api_pattern='[a-f0-9]{32}'
app_pattern='[a-f0-9]{40}'

# Carto: carto.env holds literal keys for this harness (hardcoded-keys
# mode). It's gitignored, so exclude it from the scan to avoid false positives.
# synthetics-pl-config.json (the DD-generated Private Location config) holds
# key-shaped secrets too — same treatment: gitignored + excluded here.
#
# .env holds the git commit sha, written by `make git-metadata`. A git SHA-1 is
# forty hex characters — EXACTLY the shape of a Datadog Application Key — so
# the app-key pattern below false-positives on every commit hash. Worth
# remembering if you ever write a sha into another scanned file.
#
# rum-args.env and docker-compose.override.yaml hold the RUM CLIENT token,
# which is 32-hex-shaped and so trips the API-key pattern. It is not a secret:
# a `pub`-prefixed client token is designed to be embedded in a public browser
# bundle, and this one already is. Both files are gitignored regardless,
# because the ids are org-specific.
#
# Every other file must remain key-shape-free.
findings=$(grep -rEnH \
  --include='*.yaml' --include='*.yml' --include='*.json' \
  --include='*.env' --include='*.env.*' --include='carto.env*' \
  --include='*.sh'  --include='*.py'  --include='Makefile' \
  --include='*.md'  --include='Dockerfile' --include='*.conf' \
  --exclude-dir='.git' --exclude-dir='node_modules' --exclude-dir='__pycache__' \
  --exclude='carto.env' --exclude='carto.env.bak*' --exclude='.env' \
  --exclude='docker-compose.override.yaml' --exclude='rum-args.env' \
  --exclude='synthetics-pl-config.json' \
  --binary-files=without-match \
  -e "${api_pattern}" -e "${app_pattern}" \
  . 2>/dev/null \
  | grep -v 'op://' \
  | grep -v 'CHANGE-ME' \
  | grep -v 'PASTE_YOUR' \
  | grep -v 'sha256:' \
  || true)

if [[ -n "$findings" ]]; then
  red "POTENTIAL SECRETS FOUND in harness directory:"
  echo
  echo "$findings"
  echo
  red "Datadog Seeker Scan would flag this. Move the value into 1Password"
  red "and reference via op:// in carto.env, not literally."
  exit 1
fi

green "scan clean — no literal API/APP key shapes detected"
